const input=$input.first().json;
try {
  const base=$env.INSULA_CRM_BASE_URL, apiKey=$env.INSULA_CRM_API_KEY;
  const leadId=Number(input.insulaLeadId||input.leadId||input.lead_id||input.offer?.lead_id||0);
  if(base&&apiKey&&leadId){
    const offer=input.offer||{};
    await this.helpers.httpRequest({
      method:'POST', url:base+'/api/v1/activities',
      headers:{'X-API-Key':apiKey,'Content-Type':'application/json',
        'Idempotency-Key':'acquisition:offer-draft:'+leadId+':'+String(offer.offer_id||input.offer_id||'draft')+':v1'},
      body:{lead_id:leadId,type:'stage_change',
        subject:'Offer draft prepared',
        body:'Offer draft status: '+String(offer.status||'needs_review')+'. Proposed offer: '+String(offer.proposed_offer_amount??'not set')+'. Maximum allowable offer: '+String(offer.maximum_allowable_offer??'not set')+'. CRM stage: '+String(input.crm_stage||'offer_review_needed')+'. Draft only; send authorization remains false.'},
      json:true
    });
  }
}catch(error){ console.log('InsulaCRM offer draft activity sync failed:',error.message); }
return [{json:input}];
